import { formatCents } from './format';

/** The bar and its label from known totals (also used by the listing's tiles, which already have them). */
export function progressBarHtml(raisedCents: number, goalCents: number): string {
  const pct = goalCents > 0 ? Math.min(100, Math.round((raisedCents / goalCents) * 100)) : 0;
  return (
    `<div class="pb-wrap"><div class="pb-track"><div class="pb-fill" style="width:${pct}%"></div></div>` +
    `<div class="pb-label">${formatCents(raisedCents)} raised of ${formatCents(goalCents)} goal</div></div>`
  );
}
